
(function(){
  const SHEETS={1:'data:image/jpeg;base64,',
2:'data:image/jpeg;base64,',
3:'data:image/jpeg;base64,',
4:'data:image/jpeg;base64,',
5:'data:image/jpeg;base64,',
6:'data:image/jpeg;base64,',
7:'data:image/jpeg;base64,',
8:'data:image/jpeg;base64,',
9:'data:image/jpeg;base64,',
10:'data:image/jpeg;base64,'};
  function sheetPage(service){
    service=Number(service);
    if(service>=1 && service<=11) return 1;
    if(service>=12 && service<=24) return 2;
    if(service>=25 && service<=37) return 3;
    if(service>=38 && service<=50) return 4;
    if(service>=51 && service<=63) return 5;
    if(service>=64 && service<=76) return 6;
    if(service>=77 && service<=89) return 7;
    if(service>=90 && service<=102) return 8;
    if(service>=103 && service<=115) return 9;
    if(service===116) return 10;
    return 0;
  }
  const viewer=document.getElementById('v995ServiceViewer');
  const body=document.getElementById('v995ServiceBody');
  const img=document.getElementById('v995ServiceImage');
  const title=document.getElementById('v995ServiceTitle');
  document.getElementById('v995ServiceClose').onclick=function(){
    viewer.classList.remove('open'); viewer.setAttribute('aria-hidden','true'); img.src='';
  };
  window.openWinterServiceBookPage=function(service){
    service=Number(service);
    const page=sheetPage(service);
    if(!page || !SHEETS[page]){ alert('No se ha localizado la hoja del servicio '+service+'.'); return; }
    title.textContent='Servicio '+service+' · hoja '+page+' de 10';
    img.src=SHEETS[page];
    viewer.classList.add('open'); viewer.setAttribute('aria-hidden','false');
    body.scrollTop=0; body.scrollLeft=0;
  };
})();
